class Solution {
    public boolean canFinish(int n, int[][] pres) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] p : pres) adj.get(p[1]).add(p[0]);
        int[] visited = new int[n];
        for (int i = 0; i < n; i++) {
            if (visited[i] == 0 && hasCycle(adj, visited, i)) return false;
        }
        return true;
    }
    private boolean hasCycle(List<List<Integer>> adj, int[] visited, int node) {
        visited[node] = 1;
        for (int nei : adj.get(node)) {
            if (visited[nei] == 1) return true;
            if (visited[nei] == 0 && hasCycle(adj, visited, nei)) return true;
        }
        visited[node] = 2;
        return false;
    }
}

