class Solution:
    def canFinish(self, n, pres):
        adj = [[] for _ in range(n)]
        for a, b in pres: adj[b].append(a)
        visited = [0] * n
        def dfs(node):
            if visited[node] == 1: return True
            if visited[node] == 2: return False
            visited[node] = 1
            for nei in adj[node]:
                if dfs(nei): return True
            visited[node] = 2
            return False
        return not any(dfs(i) for i in range(n) if visited[i] == 0)
